SET ROLE service_role;
DELETE FROM public.extract_test WHERE name='new';
INSERT INTO public.extract_test VALUES('new',public.test_extract(gen_random_uuid()),NULL);
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='new';
SELECT public.complete_knowledge_extraction((result->>'work_id')::uuid,started->>'server_key',1,1,'Neutral extracted text',started->>'input_hash') FROM public.extract_test WHERE name='new';
RESET ROLE;
-- Uses actual extraction setup from extraction-behavior.sql.
CREATE FUNCTION public.test_review(n text) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.read_tenant_knowledge_pending('00000000-0000-0000-0000-000000000001',(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name=n)) $$;
CREATE FUNCTION public.test_save(n text,r integer,c text DEFAULT 'Reviewed exact text') RETURNS jsonb LANGUAGE sql AS $$ SELECT public.save_tenant_knowledge_review('00000000-0000-0000-0000-000000000001',(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name=n),(SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name=n),r,c,'{"title":"Reviewed title","summary":"Reviewed summary","category":"Reviewed category","tags":["reviewed"]}') $$;
CREATE FUNCTION public.test_discard(n text,r integer) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.discard_tenant_knowledge_review('00000000-0000-0000-0000-000000000001',(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name=n),(SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name=n),r) $$;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000001',false);
SET ROLE authenticated;
SELECT public.test_assert(public.test_review('new')->>'extraction_outcome'='capability_succeeded','real extraction receipt visible');
SELECT public.test_assert(public.test_review('replacement')->>'extraction_outcome'='capability_completed_unrecorded','missing extraction receipt distinct');
SELECT public.test_assert(NOT (public.test_review('new')->'work') ? 'terminal_outcome' AND NOT public.test_review('new') ? 'extraction_input','raw work and intake payload hidden');
SELECT public.test_denied('SELECT pending_review_metadata FROM public.tenant_knowledge_docs','permission denied');
SELECT public.test_denied('UPDATE public.tenant_knowledge_docs SET last_review_operation=NULL','permission denied');
SELECT public.test_denied($q$SELECT public.list_tenant_knowledge_pending('00000000-0000-0000-0000-000000000001',NULL,51)$q$,'KNOWLEDGE_LIMIT_INVALID');
SELECT public.test_denied($q$SELECT public.list_tenant_knowledge_pending('00000000-0000-0000-0000-000000000002',NULL,20)$q$,'KNOWLEDGE_SCOPE_CHANGED');
SELECT public.test_assert(public.test_save('new',2)->>'revision'='3','review save advances CAS once');
SELECT public.test_assert(public.test_review('new')->'pending_review'->>'reviewed_content'='Reviewed exact text' AND public.test_review('new')->'pending_review'->>'extracted_content'='Neutral extracted text','save retains immutable extracted source');
SELECT public.test_assert(public.test_review('new')->'pending_review_metadata'->>'title'='Reviewed title','staged metadata readback');
SELECT public.test_denied($q$SELECT public.test_save('new',2)$q$,'KNOWLEDGE_REVISION_CONFLICT');
SELECT public.test_denied($q$SELECT public.test_save('new',3,'')$q$,'KNOWLEDGE_REVIEW_INVALID');
SELECT public.test_denied(format('SELECT public.save_tenant_knowledge_review(%L,%L,%L,3,%L,%L::jsonb)','00000000-0000-0000-0000-000000000001',(SELECT result->>'document_id' FROM public.extract_test WHERE name='new'),(SELECT result->>'work_id' FROM public.extract_test WHERE name='new'),'text','{"title":"x","summary":null,"category":null,"tags":[],"share_to_network":true}'),'KNOWLEDGE_REVIEW_INVALID');
SELECT public.test_denied(format('SELECT public.save_tenant_knowledge_review(%L,%L,%L,3,%L,%L::jsonb)','00000000-0000-0000-0000-000000000001',(SELECT result->>'document_id' FROM public.extract_test WHERE name='new'),(SELECT result->>'work_id' FROM public.extract_test WHERE name='replacement'),'text','{"title":"x","summary":null,"category":null,"tags":[]}'),'KNOWLEDGE_REVISION_CONFLICT');
SELECT public.test_denied($q$SELECT public.test_save('new',3,repeat('a',480001))$q$,'KNOWLEDGE_REVIEW_INVALID');
SELECT public.test_assert(public.test_save('replacement',3)->>'revision'='4','replacement review saved');
RESET ROLE;
SELECT public.test_assert((SELECT title='A' AND content='private A' AND summary IS NULL AND source_binding IS NULL FROM public.tenant_knowledge_docs WHERE id='20000000-0000-0000-0000-000000000001'),'replacement canonical metadata content source unchanged');
SELECT public.test_assert((SELECT content='A chunk' FROM public.tenant_knowledge_chunks WHERE doc_id='20000000-0000-0000-0000-000000000001'),'replacement chunks unchanged');
