SELECT public.test_denied($q$SELECT public.test_discard('changed',2)$q$,'KNOWLEDGE_DISCARD_IN_FLIGHT');
SELECT public.test_assert(public.test_discard('replacement',5)->>'document_removed'='false','discard replacement clears pending only');
SELECT public.test_assert(public.test_review('replacement')->'last_review_operation'->>'operation'='review_discarded' AND public.test_review('replacement')->'pending_review'='null'::jsonb,'discard replacement readback is attributable only via operation reference');
SELECT public.test_assert(public.test_discard('new',3)->>'document_removed'='true','discard draft verified removal');
