SELECT public.test_assert((SELECT status='succeeded' AND terminal_outcome->>'phase'='awaiting_review' FROM public.paige_durable_work WHERE id=(SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name='new')),'discard preserves succeeded native history');
SELECT public.test_assert((SELECT title='A' AND content='private A' AND pending_review IS NULL AND extraction_work_id IS NULL FROM public.tenant_knowledge_docs WHERE id='20000000-0000-0000-0000-000000000001'),'discard preserves published replacement content');
