-- >100 native documents, stable exclusive cursor, bounded summaries only.
SET ROLE service_role;
INSERT INTO public.extract_test SELECT 'page'||n,public.test_extract(gen_random_uuid()),NULL FROM generate_series(1,105)n;
RESET ROLE;
CREATE TABLE public.manage_pages(id uuid PRIMARY KEY);
GRANT ALL ON public.manage_pages TO authenticated;
SET ROLE authenticated;
DO $$ DECLARE cursor_id uuid; page jsonb; n integer:=0; BEGIN LOOP
 page:=public.list_tenant_knowledge_pending('00000000-0000-0000-0000-000000000001',cursor_id,20);
 PERFORM public.test_assert(jsonb_array_length(page->'items')<=20,'bounded discovery page');
 INSERT INTO public.manage_pages SELECT (x->>'document_id')::uuid FROM jsonb_array_elements(page->'items') x;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(page->'items') x WHERE x ? 'pending_review' OR x ? 'source_binding') THEN RAISE EXCEPTION 'discovery exposed content'; END IF;
 n:=n+1; cursor_id:=(page->>'next_cursor')::uuid; EXIT WHEN cursor_id IS NULL; IF n>20 THEN RAISE EXCEPTION 'cursor loop'; END IF;
 END LOOP; PERFORM public.test_assert((SELECT count(*)>=105 FROM public.manage_pages),'discovery revisits over 100 without duplicates'); END $$;
RESET ROLE;

-- Terminal failure discard preserves immutable history, including lost receipt acknowledgement.
SET ROLE service_role;
INSERT INTO public.extract_test VALUES('failed_discard',public.test_extract(gen_random_uuid()),NULL);
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='failed_discard';
SELECT public.settle_knowledge_extraction_failure((result->>'work_id')::uuid,started->>'server_key',1,'source_unavailable',false) FROM public.extract_test WHERE name='failed_discard';
RESET ROLE;
CREATE TEMP TABLE failed_before AS SELECT status,terminal_outcome FROM public.paige_durable_work WHERE id=(SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name='failed_discard');
SELECT set_config('test.receipt_fail','true',false);
SET ROLE authenticated;
SELECT public.test_assert(public.test_discard('failed_discard',1)->>'outcome'='capability_completed_unrecorded','discard receipt failure retains truthful outcome');
RESET ROLE;
SELECT set_config('test.receipt_fail','false',false);
SELECT public.test_assert((SELECT (w.status,w.terminal_outcome)=(b.status,b.terminal_outcome) FROM public.paige_durable_work w,failed_before b WHERE w.id=(SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name='failed_discard')),'failed terminal outcome unchanged by discard');
-- Existing company operator is scoped to its selected company; another company fails.
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000002',false);
SET ROLE authenticated;
SELECT public.test_assert(public.list_tenant_knowledge_pending('00000000-0000-0000-0000-000000000003',NULL,20)->>'tenant_id'='00000000-0000-0000-0000-000000000003','company operator selected scope');
SELECT public.test_denied($q$SELECT public.list_tenant_knowledge_pending('00000000-0000-0000-0000-000000000004',NULL,20)$q$,'KNOWLEDGE_SCOPE_CHANGED');
RESET ROLE;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000001',false);
